<?= $this->section('scripts') ?><script>
const BASE='<?= base_url() ?>';$('#addTaskForm').on('submit',function(e){e.preventDefault();showLoader('Adding...');$.post(BASE+'admin/tasks/store',$(this).serialize(),r=>{hideLoader();showToast(r.message,r.status);if(r.status==='success')location.reload()},'json')});
$(document).on('change','.kanban-assignee',function(e){e.stopPropagation();const s=this;s.disabled=true;$.post(BASE+'admin/tasks/update/'+s.dataset.id,{assigned_to:s.value,csrf_test_name:getCsrfToken()},r=>{s.disabled=false;showToast(r.message,r.status);if(r.status!=='success')location.reload()},'json').fail(()=>location.reload())});
let dragged=null;document.querySelectorAll('.kanban-card').forEach(c=>{c.addEventListener('dragstart',()=>{dragged=c;c.classList.add('opacity-50')});c.addEventListener('dragend',()=>{c.classList.remove('opacity-50');dragged=null})});document.querySelectorAll('.kanban-col').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();if(dragged&&dragged.parentElement!==col)col.appendChild(dragged)});col.addEventListener('drop',e=>{e.preventDefault();if(!dragged)return;showLoader('Saving...');$.post(BASE+'admin/tasks/reorder',{status:col.dataset.status,ids:Array.from(col.querySelectorAll('.kanban-card')).map(x=>x.dataset.id),csrf_test_name:getCsrfToken()},r=>{hideLoader();showToast(r.message,r.status)},'json')})});
let delId=null;$(document).on('click','.btn-del-task',function(e){e.stopPropagation();delId=$(this).data('id');$('#ngConfirmTitle').text($(this).data('confirm-title'));$('#ngConfirmMessage').text($(this).data('confirm'));$('#ngConfirmYes').text($(this).data('confirm-yes'));bootstrap.Modal.getOrCreateInstance(document.getElementById('ngConfirmModal')).show()});$('#ngConfirmYes').off('click').on('click',function(){if(!delId)return;bootstrap.Modal.getInstance(document.getElementById('ngConfirmModal')).hide();showLoader('Deleting...');$.post(BASE+'admin/tasks/delete/'+delId,{csrf_test_name:getCsrfToken()},r=>{hideLoader();showToast(r.message,r.status);if(r.status==='success')location.reload()},'json');delId=null});
</script><?= $this->endSection() ?>